397	    /**
398	     * Handles exception thrown by Bean Validation on controller methods parameters
399	     *
400	     * @param e The {@link MethodArgumentNotValidException} to be handled
401	     * @param request {@link HttpServletRequest} object referring to the current request.
402	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
403	     */
404	    @ExceptionHandler(MethodArgumentNotValidException.class)
405	    @ResponseBody
406	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
407	        HttpStatus status = HttpStatus.BAD_REQUEST;
408	        BindingErrorsResponse errors = new BindingErrorsResponse();
409	        BindingResult bindingResult = e.getBindingResult();
410	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
411	        if (bindingResult.hasErrors()) {
412	            errors.addAllErrors(bindingResult);
413	            List<String> errorFields = bindingResult.getFieldErrors().stream()
414	                .map(org.springframework.validation.FieldError::getField)
415	                .distinct()
416	                .toList();
417	            detail.setProperty("errors", errorFields);
418	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
419	                .map(fieldError -> {
420	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
421	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
422	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
423	                        fieldError.getField(),
424	                        defaultMessage,
425	                        rejectedValue);
426	                    return new ValidationMessageDto(message)
427	                        .putAdditionalProperty("field", fieldError.getField())
428	                        .putAdditionalProperty("rejectedValue", rejectedValue)
429	                        .putAdditionalProperty("defaultMessage", defaultMessage);
430	                })
431	                .toList();
432	            logger.debug("Validation error at {} {}: {}",
433	                request.getMethod(),
434	                request.getRequestURI(),
435	                bindingResult.getFieldErrors());
436	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
437	            return ResponseEntity.status(status).body(detail);
438	        }
439	        return ResponseEntity.status(status).body(detail);
440	    }
441	
442	}
