17	package org.springframework.samples.petclinic.util;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.security.NoSuchAlgorithmException;
22	import java.util.Locale;
23	
24	/**
25	 * Helpers for the "household" a pet owner belongs to. Two owners share a household when they have
26	 * the same last name and postcode; the identity is derived deterministically from the normalized
27	 * last name (surrounding whitespace trimmed, internal whitespace runs collapsed to a single space,
28	 * lower-cased) and the postcode, so values that differ only in letter case or spacing of the last
29	 * name map to one household.
30	 */
31	public final class Households {
32	
33	    private Households() {
34	    }
35	
36	    /**
37	     * Normalizes a value for household comparison: {@code null} becomes an empty string, surrounding
38	     * whitespace is trimmed, internal runs of whitespace collapse to a single space and the result is
39	     * lower-cased.
40	     */
41	    public static String normalize(String value) {
42	        if (value == null) {
43	            return "";
44	        }
45	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
46	    }
47	
48	    /**
49	     * Returns the stable, shared identifier for the household of the owner with the given last name
50	     * and postcode. The value is the first 12 hex characters of the SHA-256 digest of the normalized
51	     * last name, a {@code '|'} separator and the postcode, so every owner sharing a last name and
52	     * postcode (the two values the household is keyed on) is deterministically assigned the same
53	     * identifier.
54	     *
55	     * @param lastName the owner's last name
56	     * @param postcode the owner's postcode, or {@code null} when none
57	     * @return the household identifier
58	     */
59	    public static String householdId(String lastName, String postcode) {
60	        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
61	        return sha256hex(key).substring(0, 12);
62	    }
63	
64	    /**
65	     * Builds an owner's {@code identityKey}: the single derived value all duplicate detection is
66	     * expressed through. It is the full lower-case hex SHA-256 digest of
67	     * {@code '<normalizedTelephone>|<lowerEmail or empty>|<soundex(lastName)>'} (a {@code null}
68	     * telephone or email contributes an empty segment; the email is lower-cased and the last name is
69	     * reduced to its {@link #soundex(String) soundex} code). Two owners are duplicates only when their
70	     * whole identity keys are equal, so household members sharing a last name (hence a soundex) but
71	     * carrying different telephones have different keys and are not hard duplicates.
72	     *
73	     * @param telephone the owner's normalized (E.164) telephone
74	     * @param email     the owner's normalized email, or {@code null} when none
75	     * @param lastName  the owner's last name (contributes its soundex code)
76	     * @return the derived identity key (a 64-character lower-case hex string)
77	     */
78	    public static String identityKey(String telephone, String email, String lastName) {
79	        String key = (telephone == null ? "" : telephone) + "|"
80	            + (email == null ? "" : email.toLowerCase(Locale.ROOT)) + "|"
81	            + soundex(lastName);
82	        return sha256hex(key);
83	    }
84	
85	    /**
86	     * Computes the American Soundex code of a name: its first letter followed by three digits encoding
87	     * the significant consonants, padded with {@code '0'} and truncated to four characters. Non-letter
88	     * characters are ignored and the input is treated case-insensitively, so names differing only in
89	     * case, spacing or minor spelling map to the same code. A {@code null} or letter-free value yields
90	     * an empty string.
91	     *
92	     * @param value the name to encode
93	     * @return the four-character Soundex code, or an empty string when there is no letter to encode
94	     */
95	    public static String soundex(String value) {
96	        if (value == null) {
97	            return "";
98	        }
99	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
100	        if (letters.isEmpty()) {
101	            return "";
102	        }
103	        StringBuilder code = new StringBuilder();
104	        code.append(letters.charAt(0));
105	        char previous = soundexDigit(letters.charAt(0));
106	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
107	            char c = letters.charAt(i);
108	            if (c == 'H' || c == 'W') {
109	                // 'H'/'W' are transparent: they neither code nor reset the previous digit, so two
110	                // like-coded consonants separated only by them merge into one digit.
111	                continue;
112	            }
113	            char digit = soundexDigit(c);
114	            if (digit != '0' && digit != previous) {
115	                code.append(digit);
116	            }
117	            previous = digit;
118	        }
119	        while (code.length() < 4) {
120	            code.append('0');
121	        }
122	        return code.substring(0, 4);
123	    }
124	
125	    /**
126	     * Maps a single upper-case letter to its Soundex digit, returning {@code '0'} for vowels and the
127	     * letters ('A', 'E', 'I', 'O', 'U', 'Y', 'H', 'W') that do not contribute a digit.
128	     */
129	    private static char soundexDigit(char c) {
130	        switch (c) {
131	            case 'B': case 'F': case 'P': case 'V':
132	                return '1';
133	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
134	                return '2';
