544	
545	    /**
546	     * Computes the {@code membershipLevel} to store for the owner being created, applying the household
547	     * ceiling. The owner's natural level is first derived from their own fields (see
548	     * {@link org.springframework.samples.petclinic.util.Memberships#membershipLevel(String, Integer, Integer, java.time.LocalDate)}).
549	     * It is then capped so it cannot exceed one above the current maximum {@code membershipLevel} among
550	     * the owner's existing household members (the non-deleted owners sharing its {@code householdId}, see
551	     * {@link Households#householdId}). When the owner has no existing household member no cap applies and
552	     * the natural level is returned.
553	     *
554	     * @param owner the owner being created, with its level-affecting fields already populated
555	     * @return the (possibly capped) membership level to store on the owner
556	     */
557	    private int cappedMembershipLevel(Owner owner) {
558	        int naturalLevel = org.springframework.samples.petclinic.util.Memberships.membershipLevel(
559	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
560	        String householdId = Households.householdId(owner.getLastName(), owner.getPostcode());
561	        java.util.OptionalInt maxMemberLevel = this.clinicService.findAllOwners().stream()
562	            .filter(this::isNotDeleted)
563	            .filter(existing -> householdId.equals(
564	                Households.householdId(existing.getLastName(), existing.getPostcode())))
565	            .mapToInt(this::effectiveMembershipLevel)
566	            .max();
567	        if (maxMemberLevel.isEmpty()) {
568	            return naturalLevel;
569	        }
570	        return Math.min(naturalLevel, maxMemberLevel.getAsInt() + 1);
571	    }
572	
573	    /**
574	     * Returns an existing owner's effective {@code membershipLevel}: the stored value when present (the
575	     * value assigned, and possibly capped, when that owner was created), otherwise the level derived
576	     * from its own fields for owners that predate the stored level (e.g. seed data).
577	     *
578	     * @param owner an existing owner
579	     * @return the owner's effective membership level
580	     */
581	    private int effectiveMembershipLevel(Owner owner) {
582	        if (owner.getMembershipLevel() != null) {
583	            return owner.getMembershipLevel();
584	        }
585	        return org.springframework.samples.petclinic.util.Memberships.membershipLevel(
586	            owner.getEmail(), owner.getNamesakeCount(), owner.getHouseholdSize(), owner.getRegistrationDate());
587	    }
588	
589	    /**
590	     * Finds the existing owner, if any, that the owner being created is a soft duplicate of: an owner
591	     * sharing this owner's {@code soundex(lastName)} and postcode (an exact match of the stored 4-digit
592	     * value) while carrying a <em>different</em> {@code identityKey}. A soft match is distinct from the
593	     * hard duplicate rejected earlier by {@link #rejectDuplicateIdentity} (which requires an identical
594	     * identity key): the owner is still created, but flagged. Because the telephone is part of the
595	     * identity key, two owners with the same last name and postcode but different telephones are a soft
596	     * match rather than a hard duplicate. When more than one existing owner matches, the earliest
597	     * (lowest id) is returned so the reference is deterministic. An owner with no postcode can never
598	     * soft-match.
599	     *
600	     * @param owner the owner being created, with its telephone and postcode already normalized/validated
601	     * @return the id of the matching existing owner, or {@code null} when there is no soft match
