		int idb = createOwnerOk(b);
		int la = fetchOwner(ida).get("membershipLevel").asInt();
		int lb = fetchOwner(idb).get("membershipLevel").asInt();
		assertTrue(lb <= la + 1, "la=" + la + " lb=" + lb);
	}
}

